import { readFile, mkdir, writeFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
import { dirname, resolve } from 'node:path';
import { parseDocument } from 'yaml';
import { format, resolveConfig } from 'prettier';

const root = process.cwd();
const sourcePath =
  '_bmad-output/planning-artifacts/ux-designs/ux-agency-portfolio-2026-10-21/DESIGN.md';
const outputs = {
  scss: 'src/styles/_tokens.scss',
  json: 'src/app/core/schemas/design-tokens.json',
};
const banner =
  'GENERATED by scripts/design-tokens.mjs from DESIGN.md — do not edit. Run npm run tokens:build.';
const groups = {
  colors: 'color',
  typography: 'typography',
  spacing: 'spacing',
  rounded: 'rounded',
  elevation: 'elevation',
  motion: 'motion',
  breakpoints: 'bp',
  components: 'component',
};
const metadata = new Set([
  'title',
  'status',
  'created',
  'updated',
  'sources',
  'version',
  'name',
  'description',
]);
const kebab = (value) =>
  value.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`).replace(/^-/, '');
const keyName = (value) => (value === 'DEFAULT' ? 'default' : kebab(value));
const componentProperty = (name, field) => {
  const stroke =
    /^(?:focus-ring.*|divider.*|nav-link-current|carousel-thumb-current)$/.test(name) ||
    name.endsWith('-outline');
  return field === 'height'
    ? 'min-height'
    : field === 'backgroundColor' && stroke
      ? 'stroke-color'
      : kebab(field);
};
const property = (path) => {
  const parts = path.slice(1);
  if (path[0] === 'components' && parts.length === 2)
    parts[1] = componentProperty(parts[0], parts[1]);
  return `--kva-${groups[path[0]]}-${parts.map(keyName).join('-')}`;
};
const fail = (path, reason) => {
  throw new Error(`${path}: ${reason}`);
};
const object = (value, path) => {
  if (!value || typeof value !== 'object' || Array.isArray(value))
    fail(path, 'expected token mapping');
  return value;
};
const length = /^(?:0|\d+(?:\.\d+)?)px$/;
const number = /^(?:0|\d+(?:\.\d+)?)$/;
const color = /^#[\da-f]{6}(?:[\da-f]{2})?$/i;
const reference = /^\{([\w-]+(?:\.[\w-]+)+)\}$/;
const typographyProperties = [
  'fontFamily',
  'fontSize',
  'fontWeight',
  'lineHeight',
  'letterSpacing',
];

export async function buildTokenFiles(designMarkdown) {
  const frontmatter = /^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/.exec(designMarkdown);
  if (!frontmatter) fail('frontmatter', 'expected YAML delimiters');
  const document = parseDocument(frontmatter[1]);
  if (document.errors.length) fail('frontmatter', document.errors[0].message);
  const source = object(document.toJS(), 'frontmatter');
  for (const [group, values] of Object.entries(source)) {
    if (metadata.has(group)) continue;
    if (!Object.hasOwn(groups, group)) fail(group, 'unknown token group');
    object(values, group);
    for (const [key, value] of Object.entries(values)) {
      const path = `${group}.${key}`;
      if (!/^(?:[a-z][a-z\d-]*|\d+|DEFAULT)$/.test(key)) fail(path, 'invalid token name');
      if (group === 'typography') {
        object(value, path);
        if (key.endsWith('-lg') && !Object.hasOwn(values, key.slice(0, -3)))
          fail(path, 'orphan responsive role');
        for (const required of typographyProperties.slice(0, 4)) {
          if (!Object.hasOwn(value, required))
            fail(`${path}.${required}`, 'missing typography property');
        }
        for (const [name, scalar] of Object.entries(value)) {
          const valid =
            typeof scalar === 'string' &&
            (name === 'fontFamily'
              ? /^[a-z][a-z\d ,'-]*$/i.test(scalar)
              : name === 'fontSize'
                ? length.test(scalar)
                : name === 'fontWeight'
                  ? /^(?:[1-9]00|[1-9]\d{0,2}|1000)$/.test(scalar)
                  : name === 'lineHeight'
                    ? number.test(scalar) && Number(scalar) > 0
                    : name === 'letterSpacing'
                      ? /^-?\d+(?:\.\d+)?(?:em|px)$/.test(scalar)
                      : false);
          if (!valid) fail(`${path}.${name}`, 'malformed typography value');
        }
      } else if (group === 'components') {
        object(value, path);
        for (const [name, scalar] of Object.entries(value)) {
          if (
            !/^[a-z][a-zA-Z\d]*$/.test(name) ||
            typeof scalar !== 'string' ||
            !(
              reference.test(scalar) ||
              color.test(scalar) ||
              length.test(scalar) ||
              number.test(scalar) ||
              scalar === 'none'
            )
          ) {
            fail(`${path}.${name}`, 'malformed component value');
          }
        }
      } else {
        const valid =
          typeof value === 'string' &&
          (group === 'colors'
            ? color.test(value)
            : ['spacing', 'rounded', 'breakpoints'].includes(group)
              ? length.test(value)
              : group === 'elevation'
                ? value === 'none' ||
                  /^(?:-?\d+(?:\.\d+)?(?:px)?\s+){2,3}(?:#[\da-f]{6,8}|rgba?\([\d.,%\s]+\))$/i.test(
                    value,
                  )
                : group === 'motion'
                  ? length.test(value) ||
                    number.test(value) ||
                    /^\d+(?:\.\d+)?ms$/.test(value) ||
                    /^cubic-bezier\(\s*-?\d+(?:\.\d+)?\s*,\s*-?\d+(?:\.\d+)?\s*,\s*-?\d+(?:\.\d+)?\s*,\s*-?\d+(?:\.\d+)?\s*\)$/.test(
                      value,
                    )
                  : false);
        if (!valid) fail(path, 'malformed token value');
      }
    }
  }
  for (const group of Object.keys(groups)) {
    if (!Object.hasOwn(source, group)) fail(group, 'missing token group');
  }
  for (const key of ['none', 'DEFAULT']) {
    if (!Object.hasOwn(source.rounded, key)) fail(`rounded.${key}`, 'missing required token');
  }
  if (!source.breakpoints.desktop) fail('breakpoints.desktop', 'missing desktop breakpoint');

  const resolveValue = (value, owner, trail = []) => {
    const match = reference.exec(value);
    if (!match) return { value, path: null };
    const path = match[1].split('.');
    if (!Object.hasOwn(groups, path[0]) || trail.includes(match[1]))
      fail(owner, `invalid reference ${value}`);
    let target = source;
    for (const part of path) {
      if (!target || typeof target !== 'object' || !Object.hasOwn(target, part))
        fail(owner, `unresolved reference ${value}`);
      target = target[part];
    }
    if (typeof target === 'string') {
      const resolved = resolveValue(target, owner, [...trail, match[1]]);
      return { value: resolved.value, path: resolved.path ?? path };
    }
    if (path[0] === 'typography' && path.length === 2) return { value: target, path };
    fail(owner, `reference must target a scalar or typography role: ${value}`);
  };

  const base = [];
  const desktop = [];
  const json = { $comment: banner };
  for (const [group, values] of Object.entries(source)) {
    if (metadata.has(group)) continue;
    const exported = {};
    json[groups[group]] = exported;
    for (const [key, value] of Object.entries(values)) {
      if (group === 'typography') {
        exported[key] = value;
        const declarations = key.endsWith('-lg') ? desktop : base;
        const role = key.endsWith('-lg') ? key.slice(0, -3) : key;
        for (const [name, scalar] of Object.entries(value)) {
          declarations.push(`${property([group, role, name])}: ${scalar};`);
        }
      } else if (group === 'components') {
        exported[key] = {};
        for (const [name, scalar] of Object.entries(value)) {
          const owner = `${group}.${key}.${name}`;
          const resolved = resolveValue(scalar, owner);
          if (name === 'typography') {
            if (!resolved.path || typeof resolved.value !== 'object')
              fail(owner, 'expected typography role reference');
            for (const [typeProperty, typeValue] of Object.entries(resolved.value)) {
              exported[key][kebab(typeProperty)] = typeValue;
              const role = resolved.path[1].replace(/-lg$/, '');
              base.push(
                `${property([group, key, typeProperty])}: var(${property(['typography', role, typeProperty])});`,
              );
            }
          } else {
            if (typeof resolved.value !== 'string') fail(owner, 'expected scalar reference');
            const exportedName = componentProperty(key, name);
            exported[key][exportedName] = resolved.value;
            base.push(
              `${property([group, key, exportedName])}: ${resolved.path ? `var(${property(resolved.path)})` : scalar};`,
            );
          }
        }
      } else {
        exported[key] = value;
        base.push(`${property([group, key])}: ${value};`);
      }
    }
  }
  const config = await resolveConfig(resolve(root, '.prettierrc'));
  return {
    scss: await format(
      `// ${banner}\n:root {\n${base.join('\n')}\n}\n${desktop.length ? `@media (min-width: ${source.breakpoints.desktop}) {\n:root {\n${desktop.join('\n')}\n}\n}` : ''}`,
      { ...config, parser: 'scss' },
    ),
    json: await format(JSON.stringify(json), { ...config, parser: 'json' }),
  };
}

const flatten = (value, prefix = '', result = new Map()) => {
  for (const [key, child] of Object.entries(value)) {
    const path = prefix ? `${prefix}.${key}` : key;
    if (child && typeof child === 'object') flatten(child, path, result);
    else result.set(path, String(child));
  }
  return result;
};
const scssValues = (content) => {
  const result = new Map();
  for (const match of content.matchAll(/(--kva-[\w-]+):\s*([^;]+);/g)) {
    const key = result.has(match[1]) ? `${match[1]}@desktop` : match[1];
    result.set(key, match[2].trim());
  }
  return result;
};

export async function findTokenDrift() {
  const expected = await buildTokenFiles(await readFile(resolve(root, sourcePath), 'utf8'));
  const drift = [];
  for (const [kind, file] of Object.entries(outputs)) {
    let actual;
    try {
      actual = await readFile(resolve(root, file), 'utf8');
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
      drift.push({ file, token: '<file>', expected: expected[kind], actual: '<missing>' });
      continue;
    }
    if (actual === expected[kind]) continue;
    let wanted;
    let found;
    try {
      wanted = kind === 'json' ? flatten(JSON.parse(expected[kind])) : scssValues(expected[kind]);
      found = kind === 'json' ? flatten(JSON.parse(actual)) : scssValues(actual);
    } catch {
      drift.push({ file, token: '<file>', expected: expected[kind], actual });
      continue;
    }
    const previous = drift.length;
    for (const token of new Set([...wanted.keys(), ...found.keys()])) {
      if (wanted.get(token) !== found.get(token))
        drift.push({
          file,
          token,
          expected: wanted.get(token) ?? '<missing>',
          actual: found.get(token) ?? '<missing>',
        });
    }
    if (drift.length === previous)
      drift.push({ file, token: '<format/order>', expected: expected[kind], actual });
  }
  return drift;
}

async function main() {
  if (process.argv.slice(2).some((argument) => argument !== '--check'))
    throw new Error('Usage: node scripts/design-tokens.mjs [--check]');
  if (process.argv.includes('--check')) {
    const drift = await findTokenDrift();
    for (const item of drift)
      console.error(
        `${item.file}: ${item.token}: expected ${item.expected}; actual ${item.actual}`,
      );
    if (drift.length) process.exitCode = 1;
    else console.log('Design tokens match DESIGN.md.');
    return;
  }
  const generated = await buildTokenFiles(await readFile(resolve(root, sourcePath), 'utf8'));
  for (const [kind, file] of Object.entries(outputs)) {
    await mkdir(dirname(resolve(root, file)), { recursive: true });
    await writeFile(resolve(root, file), generated[kind]);
    console.log(`Generated ${file}`);
  }
}

if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
  main().catch((error) => {
    console.error(error.message);
    process.exitCode = 1;
  });
}
